INSERT INTO `coa_client_spell_description` (`ID`, `Description`, `ToolTip`) VALUES
(500217, '目标感染枯萎病，使附近敌人在 $d 内受到 ${($d*1000/$t1)*($m1+0+$SP*0.169175)} 点暗影伤害，施放时额外造成 ${$m1+0+$SP*0.169175} 点暗影伤害。\r\n\r\n$d 后，枯萎病从目标身上爆散，造成 $500459s2 点自然伤害。', ''),
(500335, '召唤一只 |cffffffff憎恶|r 协助你战斗，占用 3 点 |cffffffff生命之力|r。\r\n\r\n它周身环绕着疾病之云，受到伤害时对附近敌人造成 ${$802353m1+$802353ppl1+$SP*0.25} 点自然伤害。\r\n\r\n|cff90ee90命令|r：立即在它周围释放强化疾病之云。', ''),
(500365, '召唤一只 |cffffffff憎恶|r 协助你战斗，占用 3 点 |cffffffff生命之力|r。\r\n\r\n它周身环绕着疾病之云，受到伤害时对附近敌人造成 ${$802353m1+$802353ppl1+$SP*0.25} 点自然伤害。\r\n\r\n|cff90ee90命令|r：立即在它周围释放强化疾病之云。', ''),
(500456, '目标感染枯萎病，使附近敌人在 $d 内受到 ${($d*1000/$t1)*($m1+0+$SP*0.169175)} 点暗影伤害，施放时额外造成 ${$m1+0+$SP*0.169175} 点暗影伤害。\r\n\r\n$d 后，枯萎病从目标身上爆散，造成 $500459s2 点自然伤害。', ''),
(500457, '目标感染枯萎病，使附近敌人在 $d 内受到 ${($d*1000/$t1)*($m1+0+$SP*0.169175)} 点暗影伤害，施放时额外造成 ${$m1+0+$SP*0.169175} 点暗影伤害。\r\n\r\n$d 后，枯萎病从目标身上爆散，造成 $500459s2 点自然伤害。', ''),
(500458, '目标感染枯萎病，使附近敌人在 $d 内受到 ${($d*1000/$t1)*($m1+0+$SP*0.169175)} 点暗影伤害，施放时额外造成 ${$m1+0+$SP*0.169175} 点暗影伤害。\r\n\r\n$d 后，枯萎病从目标身上爆散，造成 $500459s2 点自然伤害。', ''),
(500459, '目标感染枯萎病，使附近敌人在 $d 内受到 ${($d*1000/$t1)*($m1+0+$SP*0.169175)} 点暗影伤害，施放时额外造成 ${$m1+0+$SP*0.169175} 点暗影伤害。\r\n\r\n$d 后，枯萎病从目标身上爆散，造成 $500459s2 点自然伤害。', ''),
(500971, '召唤一只 |cffffffff食尸鬼|r 协助你战斗，占用 1 点 |cffffffff生命之力|r。 \r\n\r\n它的自动攻击为你恢复 ${($707000m1+$707000ppl1+(($INT*0.504)+($SP*0.504))*0.07)*0.7} 点生命值。\r\n\r\n|cff90ee90命令|r：释放吸取瘟疫，打击最多 $801514i 个附近敌人，造成 ${(($INT*0.28+$SP*0.28)*0.2+($INT*0.504+$SP*0.504)*0.2)+$801514m1} 点瘟疫伤害，并为每只 |cffffffff食尸鬼|r 恢复 ${($801514m3+$801514ppl3+$SP*0.22+$INT*.50)*0.7} 点生命值。', ''),
(504021, '命令你的 |cffffffff食尸鬼|r 释放瘟疫，吸取 $801514a1 码内的敌人，造成 ${$801514m1+$801514ppl1+$SP*0.375+$INT*.5} 点瘟疫伤害，并为每只 |cffffffff食尸鬼|r 恢复 ${($801514m3+$801514ppl3+$SP*0.22+$INT*.50)*0.7} 点生命值。\r\n\r\n@ext:Not usable while in |cFFFFFFFFUndead: Pacify|r.:ext@', ''),
(561138, '吟唱强大的仪式，在你附近召唤 $561316s1 个 |cffffffff腐烂冰霜巨人|r 协助你战斗，持续 $561316d，并产生 $/10;561317s1 点符文能量，每 $t1 秒重复一次，持续 $d。\r\n\r\n持续期间，你的亡灵爪牙必定造成暴击。被格挡、未命中、躲闪和招架的命中不会造成暴击。', ''),
(704355, '|cff3399ff需要冰霜目标|r\r\n召唤冰冷巨石砸向一名 |cff3399ff冰霜|r 敌人，造成 ${$m1+0+$spfr*1.405} 点冰霜伤害。$?s560852[\r\n\r\n此法术必定造成暴击。][]\r\n\r\n@ext:Damage increased by your Frost spell critical strike chance. :ext@', ''),
(705750, '现在造成魔法伤害时，有 $h% 的几率使你的急速提高 $705751s1%，持续 $705751d。', ''),
(707007, '召唤不息的亡者起身前进。\r\n\r\n当它们抵达敌人时会爆炸，对附近敌人造成 ${$707010m1*$<scalingbp>+$SP*.75} 点瘟疫伤害（自然或暗影法术强度），并使其移动速度降低 $707010s2%，持续 $707010d。', ''),
(707283, '你的 |cffffffff憎恶|r 和 |cffffffff腐朽巨像|r 造成的暴击现在会 |cFFFFFFFF撕咬|r 你的目标，对其造成 ${$707284m1+($SP*2.25)*0.5} 点伤害，伤害随你的等级提高。', ''),
(707399, '|cff3399ff需要冰霜目标|r\r\n召唤冰冷巨石砸向一名 |cff3399ff冰霜|r 敌人，造成 ${$m1+0+$spfr*1.405} 点冰霜伤害。$?s560852[\r\n\r\n此法术必定造成暴击。][]\r\n\r\n@ext:Damage increased by your Frost spell critical strike chance. :ext@', ''),
(707400, '|cff3399ff需要冰霜目标|r\r\n召唤冰冷巨石砸向一名 |cff3399ff冰霜|r 敌人，造成 ${$m1+0+$spfr*1.405} 点冰霜伤害。$?s560852[\r\n\r\n此法术必定造成暴击。][]\r\n\r\n@ext:Damage increased by your Frost spell critical strike chance. :ext@', ''),
(707401, '|cff3399ff需要冰霜目标|r\r\n召唤冰冷巨石砸向一名 |cff3399ff冰霜|r 敌人，造成 ${$m1+0+$spfr*1.405} 点冰霜伤害。$?s560852[\r\n\r\n此法术必定造成暴击。][]\r\n\r\n@ext:Damage increased by your Frost spell critical strike chance. :ext@', ''),
(707402, '|cff3399ff需要冰霜目标|r\r\n召唤冰冷巨石砸向一名 |cff3399ff冰霜|r 敌人，造成 ${$m1+0+$spfr*1.405} 点冰霜伤害。$?s560852[\r\n\r\n此法术必定造成暴击。][]\r\n\r\n@ext:Damage increased by your Frost spell critical strike chance. :ext@', ''),
(707911, '|cff3399ff需要冰霜目标|r\r\n召唤冰冷巨石砸向一名 |cff3399ff冰霜|r 敌人，造成 ${$m1+0+$spfr*1.405} 点冰霜伤害。$?s560852[\r\n\r\n此法术必定造成暴击。][]\r\n\r\n@ext:Damage increased by your Frost spell critical strike chance. :ext@', ''),
(712434, '使你的 |cFFFFFFFF冰川冲击|r 伤害提高 $s1%，持续 $d，可叠加 $u 次。\r\n\r\n叠加至 10 层时，你的 |cFFFFFFFF冰川冲击|r 将造成暴击，伤害提高 50%。', ''),
(801724, '向一名敌人发射寒冰锁链，每 $t1 秒造成 ${$801728m1+$801728ppl1+$spfr*0.35} 点冰霜伤害，持续 $d。\r\n\r\n每跳产生 3 到 8 点符文能量。', ''),
(803768, '制造 $s1 个 |cffffffff白骨圣物匣|r，为你恢复 $803767s1% 的已损失生命值。\r\n\r\n盟友每分钟只能使用一次 |cffffffff白骨圣物匣|r，且每场战斗只能使用一次：该计时从战斗结束时开始。与同类效果共享冷却。', ''),
(803769, '制造 $s1 个 |cffffffff白骨圣物匣|r，为你恢复 $803767s1% 的已损失生命值。\r\n\r\n盟友每分钟只能使用一次 |cffffffff白骨圣物匣|r，且每场战斗只能使用一次：该计时从战斗结束时开始。与同类效果共享冷却。', ''),
